function i(n){const t=new Date(n),o=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),r=String(t.getDate()).padStart(2,"0"),a=String(t.getHours()).padStart(2,"0"),s=String(t.getMinutes()).padStart(2,"0");return`${o}-${e}-${r} ${a}:${s}`}function u(n,t){if(!n||!t)return 0;const o=new Date(n).getTime(),e=new Date(t).getTime();return isNaN(o)||isNaN(e)?0:Math.floor((e-o)/(1e3*60))}function c(n){const t=new Date(n),e=Math.floor((new Date().getTime()-t.getTime())/1e3);if(e<60)return"just now";const r=Math.floor(e/60);if(r<60)return`${r}m ago`;const a=Math.floor(r/60);if(a<24)return`${a}h ago`;const s=Math.floor(a/24);if(s<7)return`${s}d ago`;const f=Math.floor(s/7);return f<4?`${f}w ago`:i(n)}export{c as a,i as f,u as g};
